  <script>
    const services = [
      {
        title: "Enterprise AI Strategy & Consulting ",
        description:
          "We work with enterprise leadership teams to define an AI vision aligned with business objectives, operational scale, and compliance needs. Our consulting ensures you invest in AI where it delivers real value.",
