          "Design data governance frameworks",
          "Build scalable AI roadmaps"
        ],
      },
      {
        title: "Custom AI System Development",
        description:
          "We develop enterprise-ready AI/ML systems tailored to your infrastructure, security standards, and business logic. From pilot to production, we ensure every system is robust, compliant, and optimized for scale.",
        points: [
          "Build large-scale ML architectures",
          "Integrate with ERP, CRM, and DMS",
          "Automate complex enterprise workflows",
          "Develop models with explainability (XAI)",
          "Ensure compliance with SOC2, GDPR, HIPAA"
        ],
      },
      {
        title: "Private LLMs & Internal AI Assistants",
        description:
          "We deploy private large language models securely within your cloud/on-prem environments. These enterprise-grade AI assistants help internal teams access policies, knowledge, and SOPs instantly and securely.",
        points: [
          "Train LLMs on internal enterprise data",
          "Secure RAG pipelines for internal use",
          "Integrate with tools like Confluence, SAP, Salesforce",
          "Enable SSO, RBAC, and audit trails",
          "Meet internal IT and InfoSec standards"

        ],
      },
      {
        title: "Predictive Analytics for Enterprise Operations",
        description:
          "We build predictive engines that help enterprises make data-backed decisions across supply chain, finance, HR, and sales, enabling proactive action at scale.",
        points: [
          "Forecast demand, supply, and revenue",
          "Predict employee attrition or burnout",
          "Automate financial risk scoring",
          "Improve inventory and procurement planning",
          "Visualize insights in enterprise BI tools"
        ],
      },

      {
        title: "Enterprise AI Infrastructure Setup",
        description:
          "We design, deploy, and maintain the AI infrastructure required to run secure, high-performance AI workloads across departments,  in line with your IT, compliance, and DevOps policies.",
        points: [
          "Set up cloud/on-prem AI clusters",
          "Deploy vector databases and ML pipelines",
          "Establish model monitoring and MLOps",
          "Enable version control and CI/CD for AI",
          "Ensure end-to-end security and compliance"

        ],
      },

    ];

    const buttonsContainer = document.getElementById("serviceButtons");
    const contentContainer = document.getElementById("serviceContent");

    function renderButtons(activeIndex = 0) {
      buttonsContainer.innerHTML = "";
      services.forEach((service, index) => {
        const isActive = index === activeIndex;
        const btnWrapper = document.createElement("div");
        btnWrapper.className = `rounded-xl ${isActive ? "pl-1 bg-gradient-to-b from-[#7C3BAF] to-[#E61C42]" : ""
          }`;

        btnWrapper.innerHTML = `
                <div class="bg-white flex justify-between items-center rounded-xl font-bold text-sm lg:text-base px-3 py-4 w-full shadow-[0px_4px_24px_-1px_rgba(124,59,175,0.6)] cursor-pointer" onclick="renderContent(${index})">
                <div class="w-full">${service.title}</div>
                ${isActive
